# Generated by dotfiles (src/modules/pwsh): changes here may be lost on the
# next install. Put your own settings in a profile.d drop-in of your own, or
# in the host profile (Microsoft.PowerShell_profile.ps1), which loads after
# this one.
#
# Loads the numbered drop-ins in profile.d, beside this file, in name order,
# and only in an interactive session, as zsh reads .zshrc: PowerShell also
# loads profiles for `pwsh -Command` and `-File`, such as scripts and Claude
# Code's hooks, which want none of this. -NoExit keeps a session interactive
# (VS Code's terminal starts pwsh with -NoExit -Command).

$__dotfiles_args = @([Environment]::GetCommandLineArgs() | Select-Object -Skip 1)
$__dotfiles_interactive = -not ($__dotfiles_args -match '^--?noni(n(t(e(r(a(c(t(i(v(e)?)?)?)?)?)?)?)?)?)?$') -and (
    ($__dotfiles_args -match '^--?noe(x(i(t)?)?)?$') -or
    -not ($__dotfiles_args -match '^--?(c(o(m(m(a(n(d)?)?)?)?)?)?|f(i(l(e)?)?)?|e(c|n(c(o(d(e(d(c(o(m(m(a(n(d)?)?)?)?)?)?)?)?)?)?)?)?)?)$')
)

if ($__dotfiles_interactive) {
    foreach ($__dotfiles_dropin in @(Get-ChildItem -LiteralPath (Join-Path $PSScriptRoot 'profile.d') -Filter '*.ps1' -File -ErrorAction SilentlyContinue | Where-Object { $_.Extension -eq '.ps1' } | Sort-Object Name)) {
        try {
            . $__dotfiles_dropin.FullName
        } catch {
            Write-Warning "profile.d: $($__dotfiles_dropin.Name) failed: $_"
        }
    }
}

Remove-Variable -Name __dotfiles_args, __dotfiles_interactive, __dotfiles_dropin -ErrorAction SilentlyContinue
